{{ config(
            materialized='table',
                post_hook={
                    "sql": "create table if not exists maplemonk.tira_dsr_fact_items ( order_date date, marketplace string, brand string, mrp_sales_in_inr float64, sp_sales_in_inr float64, asp float64, aov float64, target_sp_drr float64, discount_value float64, discount_percent_to_mrp float64, discount_percent_to_net_sales float64, offsite_spends float64, online_marketing_spends float64, total_marketing_spends_incl_tax float64, total_investment_marketing_discount float64, roi float64, mtd_targets float64, return_perc float64, commission_perc float64 ); insert into maplemonk.tira_dsr_fact_items (order_date, marketplace, brand) select generated_date, \'TIRA\' as marketplace, brand as brand from unnest(generate_date_array(\'2024-01-01\', \'2027-01-01\', interval 1 day)) as generated_date cross join ( select \'RAS\' as brand union all select \'MOODY\' as brand ); create table if not exists maplemonk.swiggy_dsr_fact_items ( order_date date, marketplace string, brand string, mrp_sales_in_inr float64, sp_sales_in_inr float64, asp float64, aov float64, target_sp_drr float64, discount_value float64, discount_percent_to_mrp float64, discount_percent_to_net_sales float64, offsite_spends float64, online_marketing_spends float64, total_marketing_spends_incl_tax float64, total_investment_marketing_discount float64, roi float64, mtd_targets float64, return_perc float64, commission_perc float64 ); insert into maplemonk.swiggy_dsr_fact_items (order_date, marketplace, brand) select generated_date, \'SWIGGY\' as marketplace, brand as brand from unnest(generate_date_array(\'2024-01-01\', \'2027-01-01\', interval 1 day)) as generated_date cross join ( select \'RAS\' as brand union all select \'MOODY\' as brand ); create or replace table Maplemonk.ras_ecommerce_report_intermediate as select n.date, n.Marketplace, n.Brand, n.MRP_SALE AS MRP_Sales_in_INR, n.SP_SALES AS SP_Sales_in_INR, n.ASP, n.AOV, n.TARGET_SP_DRR AS Target_SP_DRR, n.DISCOUNT_DEBIT_IN_RS AS Discount_Value, n.Disc_to_MRP_Sales AS Discount_Percent_to_MRP, n.Discount_to_net_sales AS Discount_Percent_to_Net_Sales, n.OFFSITE_SPENDS_Meta_google AS Offsite_Spends, n.TOTAL_MARKETING_SPEND AS Online_Marketing_Spends, n.TOTAL_MARKETING_SPEND_With_Taxes AS Total_Marketing_Spends_Incl_Tax, n.TOTALINVESTMENT_MARKETING_DISCOUNT_SPEND__PLA AS Total_Investment_Marketing_Discount, n.ROI, n.MTD_Targets AS MTD_Target, n.return_perc * n.SP_SALES AS Returns, n.commission_perc * n.SP_SALES AS Commissions, SAFE_DIVIDE(emt.Primary_Sales_Target,EXTRACT(DAY FROM LAST_DAY(n.date,MONTH))) AS Primary_Sales_Target, SAFE_DIVIDE(emt.Spends_by_Secondary_Target,EXTRACT(DAY FROM LAST_DAY(n.date,MONTH))) AS Spends_by_Secondary_Target, SAFE_DIVIDE(emt.Primary_by_Secondary_Target,EXTRACT(DAY FROM LAST_DAY(n.date,MONTH))) AS Primary_by_Secondary_Target, SAFE_DIVIDE(emt.Spends_by_Primary_Revenue_Target,EXTRACT(DAY FROM LAST_DAY(n.date,MONTH))) AS Spends_by_Primary_Revenue_Target, SAFE_DIVIDE(emt.Total_Exps_Onsite_Target,EXTRACT(DAY FROM LAST_DAY(n.date,MONTH))) AS Total_Exps_Onsite_Target, SAFE_DIVIDE(emt.Secondary_Sales_Target,EXTRACT(DAY FROM LAST_DAY(n.date,MONTH))) AS Secondary_Sales_Target, SAFE_DIVIDE(emt.Revenue_Primaries_GST_Target,EXTRACT(DAY FROM LAST_DAY(n.date,MONTH))) AS Revenue_Primaries_GST_Target, SAFE_DIVIDE(emt.Discount_and_CCOGS_Target,EXTRACT(DAY FROM LAST_DAY(n.date,MONTH))) AS Discount_and_CCOGS_Target, SAFE_DIVIDE(emt.Offsite_R_and_R_Spends_Target,EXTRACT(DAY FROM LAST_DAY(n.date,MONTH))) AS Offsite_R_and_R_Spends_Target, SAFE_DIVIDE(emt.Marketing_and_Commission_Target,EXTRACT(DAY FROM LAST_DAY(n.date,MONTH))) AS Marketing_and_Commission_Target, ndt.Total_Invoice_Value as Primary_Sales from maplemonk.Nykaa_DSR_Fact_Items n left join ( select Brand, Marketplace, PO_Status, PO_date, sum(ifnull(Total_Invoice_Value,0)) as Total_Invoice_Value, sum(ifnull(Supplied_Value,0)) as Supplied_Value, sum(ifnull(Open_PO_Quantity,0)) as Open_PO_Quantity, sum(ifnull(PO_Quantity,0)) as PO_Quantity, sum(ifnull(InTransit_Qty,0)) as InTransit_Qty from maplemonk.Overall_Dispatch_Tracker WHERE lower(marketplace) LIKE \'%nykaa%\' group by 1,2,3,4 qualify row_number() over (partition by po_date,marketplace,brand) = 1 ) ndt on Date(ndt.po_date) = date(n.date) and lower(ndt.marketplace) = lower(n.marketplace) and upper(ndt.brand) = upper(n.brand) left join (select brand, marketplace, month, avg(Primary_Sales) as primary_sales_Target, avg(Secondary_Sales_GST) as Secondary_Sales_Target, avg(Total_Exps_Onsite / NULLIF(Secondary_Sales_GST,0)) as Spends_by_Secondary_Target, avg(Primary_Sales / NULLIF(Secondary_Sales_GST,0)) as Primary_by_Secondary_Target, avg(Total_Exps_Onsite / NULLIF(Primary_Sales,0)) as Spends_by_Primary_Revenue_Target, sum(Total_Exps_Onsite+Commission) as Marketing_and_Commission_Target, avg(Total_Exps_Onsite) as Total_Exps_Onsite_Target, avg(Revenue_Primaries_GST) as Revenue_Primaries_GST_Target, avg(Discount_cccogs) as Discount_and_CCOGS_Target, avg(Retention) as retention_Target, avg(Offsite_R_and_R_Spends) as Offsite_R_and_R_Spends_Target from maplemonk.ecommerce_marketplace_target where upper(marketplace) = \'NYKAA\' group by 1,2,3) emt on lower(emt.marketplace) = lower(n.marketplace) and upper(emt.brand) = upper(n.brand) and LAST_DAY(n.date,month) = emt.month UNION ALL SELECT n.date , n.Marketplace, n.Brand, n.MRP_Sales AS MRP_Sales_in_INR, n.Total_sales AS SP_Sales_in_INR, NULL AS ASP, n.AOV, NULL AS Target_SP_DRR, NULL AS Discount_Value, NULL AS Discount_Percent_to_MRP, NULL AS Discount_Percent_to_Net_Sales, n.Offsite_Spends, n.Spends AS Online_Marketing_Spends, n.Spends_Incl_Taxes AS Total_Marketing_Spends_Incl_Tax, NULL AS Total_Investment_Marketing_Discount, n.ROI, n.MTD_Targets AS MTD_Target, n.return_perc * n.Total_sales AS Returns, n.commission_perc * n.Total_sales AS Commissions, SAFE_DIVIDE(emt.Primary_Sales_Target,EXTRACT(DAY FROM LAST_DAY(n.date,MONTH))) AS Primary_Sales_Target, SAFE_DIVIDE(emt.Spends_by_Secondary_Target,EXTRACT(DAY FROM LAST_DAY(n.date